'use strict';
const fs=require('fs'),path=require('path'),crypto=require('crypto'),sharp=require('../../vendor/upscale/node_modules/sharp'),{DATA_DIR}=require('./paths'),{db}=require('./db'),{decrypt}=require('./crypto');
const active=new Map();db.exec('CREATE TABLE IF NOT EXISTS monday_component_tasks(id TEXT PRIMARY KEY,status TEXT,result TEXT)');
function aiConfigured(){return !!db.prepare("SELECT id FROM accounts WHERE enabled=1 AND credentials_encrypted IS NOT NULL LIMIT 1").get()}
function textOutput(node,inputs){const kind=node.data.kind;if(kind==='promptList'){const text=[inputs.prompt?.text,node.data.text].filter(Boolean).join('\n\n'),texts=require('./spaceSpec').parsePromptList(text);return {text:texts.join('\n\n'),texts,mediaType:'text'}}if(kind==='table'){const rows=node.data.rows||[];return {text:node.data.format==='json'?JSON.stringify(rows,null,2):rows.map(r=>r.map(c=>/[\t\r\n"]/.test(c)?'"'+c.replace(/"/g,'""')+'"':c).join('\t')).join('\n'),mediaType:'text'}}const parts=Object.entries(inputs).filter(([h])=>h==='prompt').flatMap(([,v])=>v.texts||[v.text]).filter(Boolean);return {text:kind==='joinText'?[...parts,node.data.text].filter(Boolean).join(node.data.separator??'\n\n'):node.data.text||'',mediaType:'text'}}
async function aiPrompt(key,inputs,node){const jobId='text_'+crypto.createHash('sha256').update(key).digest('hex').slice(0,20),prompt=[inputs.prompt?.text,node.data.text].filter(Boolean).join('\n\n');if(!prompt.trim())throw Error('Chưa có yêu cầu viết prompt');if(!aiConfigured())throw Error('Thêm tài khoản MUSE trong Cài đặt để viết prompt');const {dispatcher}=require('./dispatcher');const instruction=node.data.jsonMode?'Return only a valid JSON object matching the requested schema. No Markdown, prose wrapper, or image generation.':node.data.listMode?'Viết danh sách prompt: mỗi mục là một prompt hoàn chỉnh trên một đoạn riêng, cách nhau bằng dòng trống. Không thêm lời dẫn.':'Viết một prompt hoàn chỉnh, giữ nguyên @tag, danh tính, trang phục và các ràng buộc; chỉ trả nội dung prompt.';db.prepare("INSERT OR IGNORE INTO jobs(id,prompt,ref_tags,media_type,status,progress,duration,ratio,attempts,max_retries,timeout_minutes,batch_id,sort_order,created_at) VALUES(?,?,?,'text','pending',0,0,'1:1',0,0,5,?,0,datetime('now'))").run(jobId,instruction+'\n\n'+prompt,JSON.stringify(node.data.refTags||[]),'space_prompt_'+key);const existing=db.prepare('SELECT status FROM jobs WHERE id=?').get(jobId);if(['pending','running'].includes(existing?.status)){if(!dispatcher.isRunning())dispatcher.start(require('./ws').broadcast);else dispatcher.trigger()}const ctrl=new AbortController();active.set(key,ctrl);try{while(true){if(ctrl.signal.aborted)throw Error('Đã dừng viết prompt');const job=db.prepare('SELECT status,error,video_url FROM jobs WHERE id=?').get(jobId);if(['failed','stopped'].includes(job?.status))throw Error(job.error||'Tác vụ MUSE đã dừng');if(job?.status==='completed'){const file=require('./spaceMedia').managed(job.video_url),text=fs.readFileSync(file,'utf8');return {text,texts:node.data.listMode?require('./spaceSpec').parsePromptList(text):undefined,mediaType:'text',model:'MUSE'}}await new Promise(resolve=>{const abort=()=>{clearTimeout(timer);resolve()},timer=setTimeout(()=>{ctrl.signal.removeEventListener('abort',abort);resolve()},1000);ctrl.signal.addEventListener('abort',abort,{once:true})})}}finally{active.delete(key)}}
async function upscale(key,inputs){const base=inputs.base;if(base?.mediaType!=='image')throw Error('Nâng 4K cần ảnh đầu vào');const file=require('./spaceMedia').managed(base.url);const out=path.join(DATA_DIR,'videos','image_space_4k_'+crypto.createHash('sha256').update(key).digest('hex').slice(0,20)+'.png');const original=await sharp(file,{limitInputPixels:50000000}).metadata();if(!['png','jpeg','webp'].includes(original.format)||original.pages>1)throw Error('Chỉ nâng PNG, JPG hoặc WebP tĩnh');const rotated=[5,6,7,8].includes(original.orientation),info={width:rotated?original.height:original.width,height:rotated?original.width:original.height};const scale=3840/Math.max(info.width,info.height);await sharp(file).rotate().resize({width:Math.round(info.width*scale),height:Math.round(info.height*scale),fit:'inside',kernel:'lanczos3'}).sharpen({sigma:.8}).png().toFile(out);return {...base,url:'/videos/'+path.basename(out),width:Math.round(info.width*scale),height:Math.round(info.height*scale),refTags:[],anchorTags:base.anchorTags||base.refTags,mediaType:'image'}}
async function download(key,inputs,node){const base=inputs.base;if(base?.items?.length){const result=await require('./spaceSmart').exportItems(key,base.items,node.data.format||'png');return {...base,...result}}if(!base)throw Error('Chưa có kết quả đầu vào');const dir=path.join(DATA_DIR,'space-exports');fs.mkdirSync(dir,{recursive:true});const name='export_'+crypto.createHash('sha256').update(key).digest('hex').slice(0,20);let ext,file;if(base.text!==undefined){ext='.txt';file=path.join(dir,name+ext);fs.writeFileSync(file,base.text,'utf8')}else{const source=require('./spaceMedia').managed(base.url);ext=path.extname(source);file=path.join(dir,name+ext);fs.copyFileSync(source,file)}return {...base,savedFile:path.basename(file),downloadUrl:'/api/spaces/components/export/'+path.basename(file)}}
const router=require('express').Router();router.get('/export/:file',(req,res)=>{if(!/^export_[a-f0-9]{20}\.(zip|txt|mp4|mov|webm|png|webp|jpg|jpeg)$/i.test(req.params.file))return res.sendStatus(400);const file=path.join(DATA_DIR,'space-exports',req.params.file);if(!fs.existsSync(file))return res.sendStatus(404);res.download(file)});
router.get('/muse-status',(_,res)=>res.json({configured:aiConfigured(),provider:'MUSE'}));router.post('/export-items',async(req,res)=>{try{res.json(await require('./spaceSmart').exportItems(crypto.randomUUID(),req.body.items,req.body.format,req.body.single===true))}catch(e){res.status(400).json({error:e.message})}});
function cancel(key){active.get(key)?.abort();const jobId='text_'+crypto.createHash('sha256').update(key).digest('hex').slice(0,20);const job=db.prepare('SELECT status FROM jobs WHERE id=?').get(jobId);if(job?.status==='pending')db.prepare("UPDATE jobs SET status='stopped' WHERE id=?").run(jobId);else if(job?.status==='running')require('./dispatcher').dispatcher.stopJob(jobId)}
function pickImage(key,inputs,node){const base=inputs.base,index=node.data.frameIndex??1,items=base?.items?.length?base.items:base?[base]:[];if(!Number.isInteger(index)||index<1||index>items.length)throw Error('Danh sách chỉ có '+items.length+' ảnh; không có cảnh '+index);const item=items[index-1];if(item.mediaType!=='image'||!item.refTags?.length)throw Error('Ảnh cảnh cần được lưu vào thư viện trước khi dùng cho AI');require('./spaceMedia').managed(item.url);const {items:ignored,...single}=item;return {...single,anchorTags:base.anchorTags||item.anchorTags||base.refTags,label:node.data.label||item.label||('Cảnh '+index)}}
module.exports={pickImage,splitStoryboard:require('./spaceSmart').splitStoryboard,router,aiConfigured,textOutput,aiPrompt,upscale,download,cancel};
